const defaultState=()=>({view:'overview',requirements:structuredClone(seed.requirements),tasks:structuredClone(seed.tasks),tests:structuredClone(seed.tests),activities:structuredClone(seed.activities),selectedComponent:'onboarding-ui',doc:'release',boardFilter:'All items',reqSearch:'',reqStatus:'All statuses',reqPriority:'All priorities',qaFilter:'All results',requirementPage:1,docsApproved:false,changeCounter:1});
