const root=document.getElementById('view-root');
const modalRoot=document.getElementById('modal-root');const drawerRoot=document.getElementById('drawer-root');const toastRoot=document.getElementById('toast-root');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=name=>(name||'').split(/\s+/).map(x=>x[0]||'').join('').slice(0,2).toUpperCase();
const tag=(label,tone='gray')=>`<span class="tag ${tone}">${esc(label)}</span>`;
const toneStatus=s=>({'Approved':'green','Passed':'green','Done':'green','In review':'purple','In progress':'blue','Draft':'gray','Failed':'red','Blocked':'red','Not run':'amber','To do':'gray'}[s]||'gray');
const statusTag=s=>tag(s,toneStatus(s));
const priorityDot=p=>`<span class="priority ${p==='Critical'||p==='High'?'high':p==='Low'?'low':''}"><i></i>${esc(p)}</span>`;
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;toastRoot.appendChild(el);setTimeout(()=>el.remove(),3000)}
function addActivity(text,who='KK'){state.activities.unshift({id:`evt-${crypto.randomUUID()}`,initials:who,text,time:'Just now'});state.activities=state.activities.slice(0,20)}
function nextRequirementId(){const max=state.requirements.reduce((m,r)=>Math.max(m,Number(String(r.id).split('-')[1])||0),110);return `CG-${String(max+1).padStart(3,'0')}`}
function nextBacklogId(){const max=state.tasks.reduce((m,t)=>Math.max(m,Number(String(t.id).split('-')[1])||0),210);return `BL-${max+1}`}
function readiness(){const reqScore=state.requirements.reduce((n,r)=>n+({Draft:.25,'In progress':.5,'In review':.75,'Approved':1}[r.status]||0),0)/Math.max(1,state.requirements.length);const qaScore=state.tests.reduce((n,t)=>n+({ 'Not run':.25,'Failed':0,'Passed':1}[t.result]||0),0)/Math.max(1,state.tests.length);const docs=state.docsApproved?1:.65;const backlogScore=state.tasks.reduce((n,t)=>n+({'To do':.2,'In progress':.6,'In review':.8,'Done':1,'Blocked':0}[t.status]||0),0)/Math.max(1,state.tasks.length);return Math.round((reqScore*.3+qaScore*.3+docs*.15+backlogScore*.25)*100)}
function header(title,subtitle,actions=''){return `<div class="page-header"><div><div class="eyebrow">RETAIL BANKING · RELEASE 2.4.0</div><h1 class="page-title">${title}</h1><div class="page-subtitle">${subtitle}</div></div><div class="header-actions">${actions}</div></div>`}
function actionBtn(action,label,icon='',kind=''){return `<button class="btn ${kind}" data-action="${action}">${icon?ic(icon):''}${label}</button>`}
function statCard(label,value,sub,icon,trend=''){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${ic(icon)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<b class="${trend.startsWith('+')?'trend-up':'trend-warn'}">${trend}</b>`:''}${sub}</div></div>`}
