function renderRequirements(){
 const filtered=state.requirements.filter(r=>(`${r.id} ${r.title} ${r.owner} ${r.component}`.toLowerCase().includes(state.reqSearch.toLowerCase()))&&(state.reqStatus==='All statuses'||r.status===state.reqStatus)&&(state.reqPriority==='All priorities'||r.priority===state.reqPriority));
 const rows=filtered.map(r=>`<tr><td><button class="id-link" data-open-req="${r.id}">${r.id}</button></td><td><div class="table-primary">${esc(r.title)}</div><div class="table-secondary">${esc(componentData[r.component]?.name||r.component)}</div></td><td>${priorityDot(r.priority)}</td><td>${statusTag(r.status)}</td><td>${esc(r.owner)}</td><td><span class="coverage-wrap"><span class="coverage-bar"><span style="width:${(r.tests?.length?80:0)}%"></span></span><span>${r.tests?.length||0} tests</span></span></td><td><button class="icon-button" data-open-req="${r.id}">${ic('chevron')}</button></td></tr>`).join('');
 return `${header('Requirements','Turn business intent into structured, testable product requirements.',`${actionBtn('export-reqs','Export CSV','download')}${actionBtn('add-requirement','Add requirement','plus','primary')}`)}
 <div class="toolbar"><label class="search-box">${ic('search')}<input id="req-search" placeholder="Search requirements, owners or components…" value="${esc(state.reqSearch)}" /></label><select class="select-control" id="req-status"><option>All statuses</option>${['Draft','In progress','In review','Approved'].map(s=>`<option ${state.reqStatus===s?'selected':''}>${s}</option>`).join('')}</select><select class="select-control" id="req-priority"><option>All priorities</option>${['Critical','High','Medium','Low'].map(s=>`<option ${state.reqPriority===s?'selected':''}>${s}</option>`).join('')}</select><span style="margin-left:auto;color:#98a2b3;font-size:9px">${filtered.length} of ${state.requirements.length} requirements</span></div>
 <section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>ID</th><th>Requirement</th><th>Priority</th><th>Status</th><th>Owner</th><th>QA links</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="7"><div class="empty-state"><strong>No requirements found</strong>Try changing your search or filters.</div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Showing ${filtered.length} requirements · Sorted by recently updated</span><div class="pagination"><button class="page-btn active">1</button><button class="page-btn" disabled>2</button><button class="page-btn" disabled>→</button></div></div></section>
 <div class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><div class="section-title">Requirement quality checklist</div><div class="section-note">Use this before moving a story into development</div></div>${tag('PRODUCT OWNER CHECK','blue')}</div><div class="qa-summary"><div class="qa-mini"><span>Clear business outcome</span><strong style="font-size:13px;color:#15976b">✓ Defined</strong></div><div class="qa-mini"><span>Testable acceptance criteria</span><strong style="font-size:13px;color:#15976b">${state.requirements.filter(r=>r.criteria?.length>=3).length}/${state.requirements.length} ready</strong></div><div class="qa-mini"><span>Linked QA scenarios</span><strong style="font-size:13px;color:#15976b">${state.requirements.filter(r=>r.tests?.length).length}/${state.requirements.length} linked</strong></div></div></div>`;
}
function renderDependencies(){
 const selected=componentData[state.selectedComponent]||componentData['onboarding-ui'];const selectedId=state.selectedComponent;
 const positions={'onboarding-ui':[50,13],'kyc-service':[18,42],'customer-profile':[50,42],'document-service':[82,42],'core-banking':[28,76],'notification-service':[72,76],'audit-ledger':[50,93]};
 const edges=[['onboarding-ui','kyc-service'],['onboarding-ui','customer-profile'],['onboarding-ui','document-service'],['kyc-service','customer-profile'],['kyc-service','audit-ledger'],['customer-profile','core-banking'],['customer-profile','audit-ledger'],['document-service','audit-ledger'],['document-service','kyc-service'],['core-banking','notification-service'],['core-banking','audit-ledger'],['notification-service','audit-ledger']];
 const isConnected=(a,b)=>{const aDeps=componentData[a].deps||[],bDeps=componentData[b].deps||[];return aDeps.includes(b)||bDeps.includes(a)};
 const svgEdges=edges.map(([a,b])=>{const [x1,y1]=positions[a],[x2,y2]=positions[b];return `<line x1="${x1}%" y1="${y1}%" x2="${x2}%" y2="${y2}%" class="graph-edge ${selectedId===a||selectedId===b?'affected':''}"/>`}).join('');
 const nodes=Object.entries(componentData).map(([id,c])=>{const [x,y]=positions[id];return `<button class="graph-node ${selectedId===id?'active':''} ${isConnected(selectedId,id)?'impacted':''}" style="left:${x}%;top:${y}%" data-component="${id}"><i class="node-status ${c.status==='Attention'?'warn':c.risk==='Critical'?'risk':''}"></i><span class="node-kind">${c.type}</span><strong>${c.name}</strong><small>${c.owner}</small></button>`}).join('');
 return `${header('Dependency explorer','Understand how a change travels across services, teams and platform boundaries.',`${actionBtn('reset-graph','Reset view','filter')}${actionBtn('simulate-impact','Run impact analysis','spark','primary')}`)}
 <div class="dependency-layout"><section class="panel graph-panel"><div class="panel-head"><div><div class="section-title">Joint-account onboarding · Component map</div><div class="section-note">Select any component to inspect its upstream and downstream relationships.</div></div><div class="graph-tools">${tag('7 COMPONENTS','blue')}</div></div><div class="graph-canvas"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${svgEdges}</svg>${nodes}</div><div class="impact-legend"><span><i class="legend-dot" style="background:#4d80e8"></i>Selected component</span><span><i class="legend-dot" style="background:#9db9f4"></i>Direct dependency</span><span><i class="legend-dot" style="background:#35a982"></i>Healthy</span><span><i class="legend-dot" style="background:#e0a33d"></i>Attention</span></div></section>
 <aside class="graph-side"><section class="panel side-detail"><div class="component-symbol">${ic('nodes')}</div>${tag(selected.risk==='Critical'?'HIGH IMPACT':selected.risk.toUpperCase()+' IMPACT',selected.risk==='Critical'?'red':selected.risk==='High'?'amber':'green')}<div class="detail-title" style="margin-top:9px">${selected.name}</div><div class="detail-meta">${selected.type} · ${selected.owner}</div><div class="detail-block"><label>Component overview</label><p>${selected.desc}</p></div><div class="detail-block"><label>Direct dependencies · ${selected.deps.length}</label><div class="component-list">${selected.deps.length?selected.deps.map(id=>`<button class="component-list-item" data-component="${id}"><i></i>${componentData[id].name} <span style="margin-left:auto;color:#9aa4b3">↗</span></button>`).join(''):'<span style="font-size:9px;color:#9aa4b3">No downstream dependencies mapped.</span>'}</div></div><div class="impact-summary"><strong>Impact consideration</strong><p>${selected.riskText}</p></div></section><section class="panel side-detail"><div class="section-title">Change propagation</div><div class="section-note">For the selected component</div><div class="detail-block"><label>Functional owner</label><p>${selected.owner}</p></div><div class="detail-block"><label>Current health</label><p>${statusTag(selected.status)}</p></div><div class="detail-block"><label>Suggested validation</label><p>Review API contracts, confirm backward compatibility and update linked QA scenarios before release sign-off.</p></div></section></aside></div>`;
}
function renderBacklog(){
 const filtered=state.tasks.filter(t=>state.boardFilter==='All items'||(state.boardFilter==='Sprint 18'?true:state.boardFilter==='Blocked'?t.status==='Blocked':t.status===state.boardFilter));
 const groups=[['To do','To do'],['In progress','In progress'],['In review / Done',['In review','Done']]];
 return `${header('Product backlog','Prioritise work, make dependencies visible and keep delivery moving.',`${actionBtn('export-tasks','Export backlog','download')}${actionBtn('add-task','Add work item','plus','primary')}`)}
 <div class="board-tabs">${['All items','Sprint 18','Blocked'].map(f=>`<button class="board-tab ${state.boardFilter===f?'active':''}" data-board-filter="${f}">${f}</button>`).join('')}</div>
 <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:13px;color:#929dad;font-size:9px"><span>${filtered.length} work items · Sprint 18 · Nov 23 – Dec 04</span><span>Drag-and-drop is represented by status updates in the item detail.</span></div>
 <div class="board-layout">${groups.map(([label,statuses])=>{const arr=filtered.filter(t=>Array.isArray(statuses)?statuses.includes(t.status):t.status===statuses);return `<section class="board-column"><div class="column-head"><div class="column-title"><i class="legend-dot" style="background:${label==='To do'?'#aab4c2':label==='In progress'?'#4c82ed':'#35a47c'}"></i>${label}</div><span class="column-count">${arr.length}</span></div>${arr.map(t=>`<article class="task-card" data-open-task="${t.id}"><div class="task-card-top"><span class="task-id">${t.id} · ${t.requirement}</span>${tag(t.priority,t.priority==='Critical'||t.priority==='High'?'red':t.priority==='Medium'?'amber':'gray')}</div><h4>${esc(t.title)}</h4><div class="task-card-foot"><span class="task-meta">${t.points} pts · ${esc(t.owner)}</span><span class="task-avatar">${initials(t.owner)}</span></div></article>`).join('')||'<div class="empty-state">No items in this column</div>'}</section>`}).join('')}</div>`;
}
function renderQA(){
 const filtered=state.tests.filter(t=>state.qaFilter==='All results'||t.result===state.qaFilter);const passed=state.tests.filter(t=>t.result==='Passed').length,failed=state.tests.filter(t=>t.result==='Failed').length,notrun=state.tests.filter(t=>t.result==='Not run').length;const coverage=Math.round(passed/Math.max(1,state.tests.length)*100);
 const rows=filtered.map(t=>`<tr><td><div class="test-name"><span class="test-icon">${ic('check')}</span><div><div class="table-primary">${esc(t.name)}</div><div class="table-secondary">${t.id}</div></div></div></td><td><button class="id-link" data-open-req="${t.requirement}">${t.requirement}</button></td><td>${esc(componentData[t.component]?.name||t.component)}</td><td>${statusTag(t.result)}</td><td>${esc(t.owner)}</td><td>${esc(t.lastRun)}</td><td><button class="btn small ${t.result==='Passed'?'soft':''}" data-run-test="${t.id}">Run test</button></td></tr>`).join('');
 return `${header('QA & traceability','Connect every requirement to meaningful validation and release evidence.',`${actionBtn('export-qa','Export test results','download')}${actionBtn('run-all-tests','Run all tests','check','primary')}`)}
 <div class="qa-summary"><div class="qa-mini"><span>Passed test cases</span><strong style="color:#15976b">${passed} <small style="font:500 10px 'DM Sans';color:#98a2b3">/ ${state.tests.length}</small></strong></div><div class="qa-mini"><span>Failed scenarios</span><strong style="color:#d9485f">${failed}</strong></div><div class="qa-mini"><span>Not yet executed</span><strong style="color:#ad7a27">${notrun}</strong></div></div>
 <section class="panel table-panel"><div class="panel-head" style="padding:16px 16px 0"><div><div class="section-title">Test execution matrix</div><div class="section-note">${coverage}% of linked scenarios currently passing · ${state.tests.length} total scenarios</div></div><select class="select-control" id="qa-filter"><option>All results</option>${['Passed','Failed','Not run'].map(s=>`<option ${state.qaFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Test scenario</th><th>Requirement</th><th>Component</th><th>Result</th><th>Owner</th><th>Last run</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div><div class="table-footer"><span>Traceability connects requirement → work item → test evidence.</span><span>${coverage}% passing</span></div></section>
 <div class="panel panel-pad" style="margin-top:14px"><div class="panel-head"><div><div class="section-title">Traceability chain</div><div class="section-note">A release-ready requirement should have a complete evidence path.</div></div>${tag('END-TO-END','blue')}</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">${[['01','Requirement','Business intent'],['02','User story','Buildable scope'],['03','Test scenario','Validation evidence'],['04','Release sign-off','Approved outcome']].map((x,i)=>`<div style="padding:12px;background:#fafbfd;border:1px solid #edf1f6;border-radius:9px"><span style="font-size:8px;color:#9aa4b3">${x[0]}</span><div style="font-size:10px;font-weight:700;margin-top:7px">${x[1]}</div><div style="font-size:8px;color:#9aa4b3;margin-top:4px">${x[2]}</div></div>`).join('')}</div></div>`;
}
const docs={
 release:{kicker:'RELEASE DOCUMENTATION · R2.4.0',title:'Joint-account onboarding · Release notes',desc:'Draft release summary generated from the current requirements and backlog state.',body:()=>`<h3>Overview</h3><p>Release 2.4.0 introduces a joint-account onboarding journey that enables a primary applicant to add a second applicant and complete the required identity, document and account-creation steps within a connected workflow.</p><div class="doc-callout"><strong>Release status: Draft</strong><br>Target date: 30 November 2026 · Product owner: Kabir Khurana · Scope: Joint-account onboarding</div><h3>Capabilities in scope</h3><ul><li>Capture a second applicant and their relationship to the primary applicant.</li><li>Run identity verification independently for each applicant.</li><li>Maintain unique customer identities with a linked joint ownership relationship.</li><li>Collect applicant-level documents and consent records.</li><li>Create the joint account through the core banking integration after validations pass.</li><li>Notify applicants and preserve an audit trail of key decisions.</li></ul><h3>Delivery status</h3><ul>${state.requirements.map(r=>`<li><strong>${r.id} — ${esc(r.title)}</strong>: ${esc(r.status)} (${esc(r.priority)} priority)</li>`).join('')}</ul><h3>Known issues and follow-ups</h3><ul>${state.tests.filter(t=>t.result==='Failed').map(t=>`<li>${t.id}: ${esc(t.name)} requires investigation.</li>`).join('')||'<li>No failing QA scenarios currently recorded.</li>'}<li>Complete contract validation with the core banking team before release approval.</li><li>Confirm support and operations training material is signed off.</li></ul><h3>Release acceptance</h3><p>Release should proceed only after critical requirements are approved, high-impact dependencies are reviewed, all critical test scenarios pass, and operations documentation is approved.</p>`},
 guide:{kicker:'USER GUIDE · OPERATIONS',title:'Joint-account onboarding · User guide',desc:'Operational guidance for front-line and service operations teams.',body:()=>`<h3>Purpose</h3><p>This guide describes the intended operational journey for a joint-account application. It is a prototype document and should be validated by business operations before production use.</p><h3>1. Start an application</h3><ol><li>Open the onboarding workspace and select <strong>Start joint account</strong>.</li><li>Capture the primary applicant’s details and complete the required consent.</li><li>Select <strong>Add second applicant</strong> and capture the additional applicant’s information.</li></ol><h3>2. Complete identity and document checks</h3><ol><li>Review the applicant-level KYC status for both applicants.</li><li>Upload the required documents to the matching applicant record.</li><li>Resolve any failed or pending checks using the relevant operational process.</li></ol><h3>3. Review account setup</h3><ol><li>Confirm both customer identifiers and the selected ownership type.</li><li>Verify that all mandatory checks have passed.</li><li>Submit the account-creation request and retain the application reference.</li></ol><h3>4. Monitor and resolve exceptions</h3><p>Use the application reference to review the current stage, pending applicant and most recent exception. Do not manually repeat an account-creation request when the prior request outcome is unknown; first confirm the transaction status using its correlation reference.</p><h3>Escalation</h3><p>Escalate identity-verification failures to the KYC support owner, integration failures to the core banking support owner, and audit or consent discrepancies to the risk operations owner.</p>`},
 api:{kicker:'TECHNICAL REFERENCE · INTEGRATIONS',title:'Integration contract overview',desc:'High-level API and event boundaries for engineering and QA review.',body:()=>`<h3>Integration principles</h3><ul><li>Use a stable application reference as the correlation key across service boundaries.</li><li>Keep applicant identity and verification outcomes separate.</li><li>Make account-creation requests idempotent.</li><li>Represent asynchronous verification and document states explicitly.</li><li>Record material business decisions in the audit ledger.</li></ul><h3>Proposed service boundaries</h3><h4>Onboarding API</h4><p>Owns the application workflow, applicant collection and orchestration state.</p><h4>KYC Service</h4><p>Accepts applicant identity references and returns verification status, decision reason and provider reference.</p><h4>Customer Profile</h4><p>Maintains customer records, relationship links and individual consent references.</p><h4>Document Service</h4><p>Stores applicant-level document references, type, verification status and retention metadata.</p><h4>Core Banking API</h4><p>Accepts a validated account-creation command with applicant references and ownership configuration. Requests require an idempotency key.</p><h4>Audit Ledger</h4><p>Consumes domain events with actor, timestamp, entity, action and correlation reference.</p><div class="doc-callout"><strong>Contract note</strong><br>These are proposed interface boundaries for the prototype. Concrete endpoint paths, schemas, authentication scopes, SLAs and error codes must be confirmed with the owning engineering teams.</div><h3>Cross-cutting requirements</h3><ul><li>Authentication and role-based authorisation.</li><li>PII minimisation and masking in operational interfaces.</li><li>Consistent error model with retryability indicators.</li><li>Observability through structured logs and correlation IDs.</li></ul>`},
 demo:{kicker:'ENABLEMENT · BUSINESS DEMO',title:'Business demo & training script',desc:'A repeatable walkthrough for stakeholder demonstrations and user enablement.',body:()=>`<h3>Demo objective</h3><p>Show how the proposed joint-account journey connects applicant capture, identity verification, document collection, account creation, notifications and audit evidence.</p><h3>Suggested 12-minute flow</h3><ol><li><strong>Context (2 min):</strong> Explain the current fragmented experience and the outcome expected from the initiative.</li><li><strong>Applicant journey (3 min):</strong> Start an application, add the second applicant and show field validation.</li><li><strong>Verification (2 min):</strong> Show separate KYC and document states for each applicant, including a pending outcome.</li><li><strong>Dependency view (2 min):</strong> Open the component graph and explain downstream impact.</li><li><strong>Controls (2 min):</strong> Show the account-creation gate, notification events and audit trail.</li><li><strong>Close (1 min):</strong> Review open questions, known limitations and next release gates.</li></ol><h3>Questions to prepare for</h3><ul><li>What happens when only one applicant completes verification?</li><li>How do we prevent duplicate account creation?</li><li>Which team owns each integration and its failure path?</li><li>What evidence is required before release approval?</li></ul><h3>Training checklist</h3><ul><li>Confirm audience and role permissions.</li><li>Use non-production sample data only.</li><li>Prepare the demo application reference and expected outcomes.</li><li>Capture questions and assign follow-up owners.</li></ul>`}
};
function renderDocs(){const d=docs[state.doc]||docs.release;const override=state.docOverrides?.[state.doc];return `${header('Documentation','Keep release notes, technical references and user enablement aligned with delivery.',`${actionBtn('edit-doc','Edit draft','edit')}${actionBtn('approve-docs',state.docsApproved?'Approved':'Request approval','check',state.docsApproved?'soft':'')}${actionBtn('download-doc','Download Markdown','download','primary')}`)}<div class="docs-layout"><aside class="panel docs-nav"><div class="eyebrow" style="padding:7px 9px">DOCUMENT LIBRARY</div>${Object.entries({release:'Release notes',guide:'User guide',api:'Integration overview',demo:'Demo & training script'}).map(([id,label])=>`<button class="docs-nav-item ${state.doc===id?'active':''}" data-doc="${id}">${ic(id==='release'?'file':id==='guide'?'list':id==='api'?'nodes':'calendar')}${label}</button>`).join('')}<div style="margin:15px 8px 7px;border-top:1px solid var(--line);padding-top:14px"><div class="eyebrow">DOCUMENT HEALTH</div><div style="font-size:10px;font-weight:700;margin-top:7px">${state.docsApproved?'Approved for release':'Review required'}</div><div class="section-note">Last generated just now</div></div></aside><section class="panel docs-editor"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><div class="doc-kicker">${d.kicker}</div><div class="doc-toolbar">${actionBtn('copy-doc','Copy','copy','small')}</div></div><h2 class="doc-title">${d.title}</h2><div class="doc-description">${d.desc}</div><article class="doc-content" id="doc-content">${override?`<pre class="doc-override">${esc(override)}</pre>`:d.body()}</article><div style="margin-top:25px;padding-top:14px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;color:#9aa4b3;font-size:9px"><span>ChangeGraph · Retail Banking · Release 2.4.0</span><span>Internal working draft</span></div></section></div>`}
function render(){document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const labels={overview:'Overview',requirements:'Requirements',dependencies:'Dependencies',backlog:'Backlog',qa:'QA & traceability',documentation:'Documentation'};document.getElementById('breadcrumb-current').textContent=labels[state.view]||'Overview';document.getElementById('req-nav-count').textContent=state.requirements.length;document.getElementById('sidebar-readiness').textContent=readiness()+'%';const sideBarFill=document.querySelector('.mini-progress span');if(sideBarFill)sideBarFill.style.width=readiness()+'%';root.innerHTML=({overview:renderOverview,requirements:renderRequirements,dependencies:renderDependencies,backlog:renderBacklog,qa:renderQA,documentation:renderDocs}[state.view]||renderOverview)();persist();window.applyChangeGraphRole?.()}
function setView(view){state.view=view;drawerRoot.innerHTML='';modalRoot.innerHTML='';render();window.scrollTo({top:0,behavior:'smooth'})}
window.setChangeGraphView=setView;
window.hydrateChangeGraphState=(incoming)=>{state={...defaultState(),...incoming,view:state.view||'overview',reqSearch:'',reqStatus:'All statuses',reqPriority:'All priorities',qaFilter:'All results'};persist();render()};
window.saveCurrentChangeGraphState=()=>persist();
