function closeModal(){modalRoot.innerHTML=''}
function openDrawer(title,subtitle,body,foot=''){drawerRoot.innerHTML=`<div class="drawer-backdrop" data-close-drawer><section class="drawer" role="dialog" aria-modal="true"><div class="drawer-head"><div><div class="eyebrow">WORK ITEM DETAILS</div><div style="font-size:10px;color:#8d98a8">${subtitle}</div><h2 style="font:800 17px Manrope;margin:7px 0 0">${title}</h2></div><button class="icon-button" data-action="close-drawer">${ic('close')}</button></div><div class="drawer-body">${body}</div><div class="drawer-foot">${foot||'<button class="btn" data-action="close-drawer">Close</button>'}</div></section></div>`}
function openRequirement(id){const r=state.requirements.find(x=>x.id===id);if(!r)return;const tests=state.tests.filter(t=>t.requirement===id);const tasks=state.tasks.filter(t=>t.requirement===id);const body=`<div style="display:flex;gap:7px;flex-wrap:wrap">${tag(r.priority,r.priority==='Critical'||r.priority==='High'?'red':'amber')}${statusTag(r.status)}${tag(componentData[r.component]?.name||r.component,'gray')}</div><p class="drawer-desc" style="margin-top:14px">${esc(r.description)}</p><div class="drawer-section"><h4>Requirement information</h4><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><div class="eyebrow">OWNER</div><div style="font-size:10px;font-weight:700">${esc(r.owner)}</div></div><div><div class="eyebrow">CREATED</div><div style="font-size:10px;font-weight:700">${esc(r.created||'Today')}</div></div></div></div><div class="drawer-section"><h4>Acceptance criteria · ${r.criteria.length}</h4><div class="criteria-list">${r.criteria.map((c,i)=>`<div class="criteria-item ${i<Math.min(2,r.criteria.length)?'done':''}"><span class="check-square"></span><span>${esc(c)}</span></div>`).join('')}</div></div><div class="drawer-section"><h4>Linked work items · ${tasks.length}</h4>${tasks.length?tasks.map(t=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #f1f3f6"><div><div style="font-size:9px;color:#2866df;font-weight:700">${t.id}</div><div style="font-size:10px;font-weight:600;margin-top:3px">${esc(t.title)}</div></div>${statusTag(t.status)}</div>`).join(''):'<div class="section-note">No work items linked yet.</div>'}</div><div class="drawer-section"><h4>QA traceability · ${tests.length}</h4>${tests.length?tests.map(t=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:7px 0"><div><div style="font-size:9px;font-weight:700">${t.id}</div><div style="font-size:9px;color:#8c98a8;margin-top:3px">${esc(t.name)}</div></div>${statusTag(t.result)}</div>`).join(''):'<div class="section-note">No linked test scenarios.</div>'}</div><div class="drawer-section"><h4>Change history</h4><p class="drawer-desc">Created ${esc(r.created||'recently')} by Product. Updates are stored locally in this prototype.</p></div>`;const foot=`<button class="btn" data-action="close-drawer">Close</button><button class="btn primary" data-edit-req="${r.id}">${ic('edit')} Edit requirement</button>`;openDrawer(r.title,r.id,body,foot)}
function openTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;const req=state.requirements.find(r=>r.id===t.requirement);const body=`<div style="display:flex;gap:7px;flex-wrap:wrap">${tag(t.priority,t.priority==='Critical'||t.priority==='High'?'red':'amber')}${statusTag(t.status)}</div><p class="drawer-desc" style="margin-top:13px">Work item for ${req?esc(req.title):t.requirement}. This task contributes to the joint-account onboarding release.</p><div class="drawer-section"><h4>Work item details</h4><div class="form-field"><label>Status</label><select id="task-status-select"><option ${t.status==='To do'?'selected':''}>To do</option><option ${t.status==='In progress'?'selected':''}>In progress</option><option ${t.status==='In review'?'selected':''}>In review</option><option ${t.status==='Done'?'selected':''}>Done</option><option ${t.status==='Blocked'?'selected':''}>Blocked</option></select></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div><div class="eyebrow">OWNER</div><strong style="font-size:10px">${esc(t.owner)}</strong></div><div><div class="eyebrow">ESTIMATE</div><strong style="font-size:10px">${t.points} story points</strong></div></div></div><div class="drawer-section"><h4>Linked requirement</h4><button class="id-link" data-open-req="${t.requirement}">${t.requirement} · View requirement →</button></div><div class="drawer-section"><h4>Definition of done</h4><div class="criteria-list">${(req?.criteria||[]).slice(0,3).map(c=>`<div class="criteria-item"><span class="check-square"></span><span>${esc(c)}</span></div>`).join('')}</div></div>`;openDrawer(t.title,t.id,body,`<button class="btn" data-action="close-drawer">Cancel</button><button class="btn primary" data-save-task="${id}">Save changes</button>`)}
function requirementForm(){return `<form id="requirement-form"><div class="form-grid"><div class="form-field full"><label>Requirement title *</label><input name="title" required placeholder="e.g. Validate joint applicant ownership" maxlength="100" /></div><div class="form-field full"><label>Business context / description *</label><textarea name="description" required placeholder="What outcome does the user or business need?" maxlength="700"></textarea></div><div class="form-field"><label>Component</label><select name="component">${Object.entries(componentData).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('')}</select></div><div class="form-field"><label>Priority</label><select name="priority"><option>High</option><option>Critical</option><option selected>Medium</option><option>Low</option></select></div><div class="form-field"><label>Owner</label><input name="owner" placeholder="e.g. A. Mehta" value="Kabir Khurana" /></div><div class="form-field"><label>Status</label><select name="status"><option>Draft</option><option>In progress</option><option>In review</option><option>Approved</option></select></div><div class="form-field full"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><label>Acceptance criteria (one per line)</label><button type="button" class="link-button" data-action="suggest-criteria">✦ Suggest starter criteria</button></div><textarea name="criteria" placeholder="Given a valid application, when the user submits, then…\nRequired data is validated before processing."></textarea><span class="form-help">Rule-based starter suggestions only — refine with the business, engineering and QA teams.</span></div></div><div class="form-field" style="margin:0"><label style="display:flex;align-items:center;gap:8px;font-weight:500"><input type="checkbox" name="createTask" checked style="width:auto" /> Create a linked backlog item</label></div></form>`}
function openAddRequirement(){openModal('Add requirement','Capture a business need and make it ready for product and engineering review.',requirementForm(),`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-submit-form="requirement-form">Save requirement</button>`)}
function openNewChange(){const body=`<form id="change-form"><div class="form-grid"><div class="form-field full"><label>Change request title *</label><input name="title" required placeholder="What needs to change?" maxlength="100" /></div><div class="form-field full"><label>Business problem / desired outcome *</label><textarea name="description" required placeholder="Describe the user problem, business outcome and why this change is needed." maxlength="900"></textarea></div><div class="form-field"><label>Requested by</label><input name="requester" value="Business stakeholder" /></div><div class="form-field"><label>Impacted component</label><select name="component">${Object.entries(componentData).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('')}</select></div><div class="form-field"><label>Business priority</label><select name="priority"><option>Critical</option><option selected>High</option><option>Medium</option><option>Low</option></select></div><div class="form-field"><label>Target release</label><input value="Release 2.4.0" disabled /></div><div class="form-field full"><label>Initial considerations</label><textarea name="notes" placeholder="Known dependencies, assumptions, constraints or risks…"></textarea></div></div><div style="background:#f7faff;border:1px solid #e4edff;padding:11px;border-radius:8px;font-size:9px;color:#70809a;line-height:1.5">ChangeGraph will create a draft requirement and a linked backlog item. Suggested acceptance criteria are starting points and should be reviewed with engineering and QA.</div></form>`;openModal('New change request','Translate an incoming business request into a trackable product change.',body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-submit-form="change-form">Create change request</button>`,true)}
function openAddTask(){const body=`<form id="task-form"><div class="form-grid"><div class="form-field full"><label>Work item title *</label><input name="title" required placeholder="Describe the engineering or product task" /></div><div class="form-field"><label>Linked requirement</label><select name="requirement">${state.requirements.map(r=>`<option value="${r.id}">${r.id} · ${esc(r.title.slice(0,35))}</option>`).join('')}</select></div><div class="form-field"><label>Priority</label><select name="priority"><option>Critical</option><option selected>High</option><option>Medium</option><option>Low</option></select></div><div class="form-field"><label>Owner</label><input name="owner" value="Engineering team" /></div><div class="form-field"><label>Estimate (story points)</label><select name="points"><option>1</option><option>2</option><option selected>3</option><option>5</option><option>8</option><option>13</option></select></div></div></form>`;openModal('Add backlog item','Create a piece of work linked to a product requirement.',body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-submit-form="task-form">Create item</button>`)}
function openImpactAnalysis(){const c=componentData[state.selectedComponent];const affected=Object.entries(componentData).filter(([id,x])=>id===state.selectedComponent||x.deps.includes(state.selectedComponent)||c.deps.includes(id));const list=affected.map(([id,x])=>`<div style="display:flex;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid #f1f3f6"><div><strong style="font-size:10px">${x.name}</strong><div class="table-secondary">${x.owner}</div></div>${tag(id===state.selectedComponent?'Source':'Connected',id===state.selectedComponent?'blue':'amber')}</div>`).join('');openModal('Impact analysis','Illustrative change propagation based on the dependency map.',`<div class="impact-summary" style="margin:0"><strong>Proposed change source: ${c.name}</strong><p>${c.riskText}</p></div><div style="margin-top:16px;font-size:10px;font-weight:700">Potentially affected components · ${affected.length}</div>${list}<div class="form-help" style="margin-top:12px">This is a deterministic impact preview from the prototype’s dependency map, not an AI-generated or production-verified analysis. Confirm dependencies with component owners.</div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="go-qa">Review QA coverage</button>`)}
function openReadinessInfo(){openModal('Release readiness calculation','How the readiness indicator is calculated.',`<p class="drawer-desc">The score is a weighted indicator built from the prototype’s current data. It is meant to help teams spot gaps, not replace a formal release decision.</p><div class="criteria-list" style="margin-top:14px"><div class="criteria-item"><span class="check-square"></span><span><strong>Requirements · 30%</strong><br>Share of requirements that are approved or in review.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>QA validation · 30%</strong><br>Share of test cases currently marked Passed.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Documentation · 15%</strong><br>100% when approved, otherwise 65% draft baseline.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Backlog · 25%</strong><br>Share of backlog work items marked Done.</span></div></div><div class="doc-callout">A real release gate should also include security, performance, operational readiness, compliance and business sign-off.</div>`,`<button class="btn primary" data-action="close-modal">Got it</button>`)}
function downloadFile(filename,content,mime='text/plain'){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function docMarkdown(){const d=docs[state.doc];if(state.docOverrides?.[state.doc])return state.docOverrides[state.doc];const el=document.getElementById('doc-content');if(!el)return `${d.title}\n\n${d.desc}`;return `# ${d.title}\n\n${d.desc}\n\n${el.innerText.replace(/\n{3,}/g,'\n\n')}`}
function csv(rows,fields){const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;return [fields.join(','),...rows.map(r=>fields.map(f=>q(r[f])).join(','))].join('\n')}
function handleSubmit(form){const fd=new FormData(form);
 if(form.id==='requirement-form'){const title=fd.get('title').trim(),desc=fd.get('description').trim();if(!title||!desc)return;const id=nextRequirementId();const criteria=(fd.get('criteria')||'').split('\n').map(x=>x.trim()).filter(Boolean);const r={id,title,description:desc,component:fd.get('component'),priority:fd.get('priority'),status:fd.get('status'),owner:fd.get('owner')||'Unassigned',criteria:criteria.length?criteria:['The expected user outcome is achieved.','Invalid or incomplete data is handled with clear feedback.','The change is covered by an agreed QA scenario.'],tests:[],created:'Nov 24'};state.requirements.unshift(r);if(fd.get('createTask')&&window.CG_AUTH?.can('backlog.write'))state.tasks.unshift({id:nextBacklogId(),title:`Implement: ${title}`,requirement:id,status:'To do',priority:r.priority,owner:r.owner,points:3});addActivity(`<strong>You</strong> created ${id} · ${esc(title)}`);closeModal();setView('requirements');toast(`${id} created successfully`);}
 if(form.id==='change-form'){const title=fd.get('title').trim(),desc=fd.get('description').trim();if(!title||!desc)return;const id=nextRequirementId();const component=fd.get('component'),priority=fd.get('priority');const criteria=['The business outcome is measurable and visible to the requesting user.','The affected workflow validates required and invalid inputs.','Downstream components receive the expected data and error states.','The change is traceable through QA scenarios and release evidence.'];state.requirements.unshift({id,title,description:desc,component,priority,status:'Draft',owner:'Kabir Khurana',criteria,tests:[],created:'Nov 24',requester:fd.get('requester'),notes:fd.get('notes')});if(window.CG_AUTH?.can('backlog.write'))state.tasks.unshift({id:nextBacklogId(),title:`Assess and implement: ${title}`,requirement:id,status:'To do',priority,owner:'Product / Engineering',points:5});addActivity(`<strong>You</strong> submitted a change request ${id} · ${esc(title)}`);closeModal();setView('requirements');toast(`Change request captured as ${id}`);}
 if(form.id==='task-form'){const title=fd.get('title').trim();if(!title)return;const id=nextBacklogId();state.tasks.unshift({id,title,requirement:fd.get('requirement'),status:'To do',priority:fd.get('priority'),owner:fd.get('owner')||'Unassigned',points:Number(fd.get('points'))});addActivity(`<strong>You</strong> added ${id} to the backlog`);closeModal();setView('backlog');toast(`${id} added to backlog`);}
 if(form.id==='edit-req-form'){const r=state.requirements.find(x=>x.id===fd.get('id'));if(!r)return;r.title=fd.get('title').trim();r.description=fd.get('description').trim();r.status=fd.get('status');r.priority=fd.get('priority');addActivity(`<strong>You</strong> updated ${r.id}`);closeModal();render();toast(`${r.id} updated`);}}

document.addEventListener('click',e=>{
 const viewBtn=e.target.closest('[data-view]');if(viewBtn){setView(viewBtn.dataset.view);return}
 const reqBtn=e.target.closest('[data-open-req]');if(reqBtn){openRequirement(reqBtn.dataset.openReq);return}
 const taskBtn=e.target.closest('[data-open-task]');if(taskBtn){openTask(taskBtn.dataset.openTask);return}
 const componentBtn=e.target.closest('[data-component]');if(componentBtn){state.selectedComponent=componentBtn.dataset.component;render();return}
 const docBtn=e.target.closest('[data-doc]');if(docBtn){state.doc=docBtn.dataset.doc;render();return}
 const boardBtn=e.target.closest('[data-board-filter]');if(boardBtn){state.boardFilter=boardBtn.dataset.boardFilter;render();return}
 const testBtn=e.target.closest('[data-run-test]');if(testBtn){const t=state.tests.find(x=>x.id===testBtn.dataset.runTest);if(t){t.result=t.result==='Failed'?'Passed':'Passed';t.lastRun='Just now';addActivity(`<strong>You</strong> recorded ${t.id} as Passed`);render();toast(`${t.id} marked as passed`)}return}
 const saveTask=e.target.closest('[data-save-task]');if(saveTask){const t=state.tasks.find(x=>x.id===saveTask.dataset.saveTask);const v=document.getElementById('task-status-select')?.value;if(t&&v){t.status=v;addActivity(`<strong>You</strong> moved ${t.id} to ${v}`);drawerRoot.innerHTML='';render();toast('Work item updated')}return}
 const editReq=e.target.closest('[data-edit-req]');if(editReq){const id=editReq.dataset.editReq,r=state.requirements.find(x=>x.id===id);if(!r)return;drawerRoot.innerHTML='';const body=`<form id="edit-req-form"><input type="hidden" name="id" value="${r.id}"/><div class="form-field"><label>Title</label><input name="title" value="${esc(r.title)}" required/></div><div class="form-field"><label>Description</label><textarea name="description" required>${esc(r.description)}</textarea></div><div class="form-grid"><div class="form-field"><label>Status</label><select name="status">${['Draft','In progress','In review','Approved'].map(x=>`<option ${x===r.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Priority</label><select name="priority">${['Critical','High','Medium','Low'].map(x=>`<option ${x===r.priority?'selected':''}>${x}</option>`).join('')}</select></div></div></form>`;openModal('Edit requirement',`${id} · Update the product definition.`,body,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-submit-form="edit-req-form">Save changes</button>`);return}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action){switch(action){case'new-change':openNewChange();break;case'add-requirement':openAddRequirement();break;case'add-task':openAddTask();break;case'close-modal':closeModal();break;case'suggest-criteria':{const f=document.getElementById('requirement-form');if(f){const title=f.elements.title.value.trim()||'the requested change';const component=componentData[f.elements.component.value]?.name||'the affected component';f.elements.criteria.value=`Given ${title.toLowerCase()} is requested, when a user follows the intended workflow, then the expected business outcome is achieved.\nThe ${component} validates all mandatory inputs and returns clear feedback for invalid or incomplete data.\nThe change preserves existing behaviour for unaffected users and workflows.\nThe change is traceable to at least one QA scenario, with expected results and an agreed owner.`;toast('Starter criteria added — review before approval')}break;}case'close-drawer':drawerRoot.innerHTML='';break;case'simulate-impact':openImpactAnalysis();break;case'reset-graph':state.selectedComponent='onboarding-ui';render();break;case'readiness-info':openReadinessInfo();break;case'go-qa':closeModal();setView('qa');break;case'export-report':downloadFile('ChangeGraph-release-report.json',JSON.stringify({release:'2.4.0',readiness:readiness(),requirements:state.requirements,tasks:state.tasks,tests:state.tests},null,2),'application/json');toast('Release report exported');break;case'export-reqs':downloadFile('ChangeGraph-requirements.csv',csv(state.requirements,['id','title','description','component','priority','status','owner']),'text/csv');toast('Requirements exported');break;case'export-tasks':downloadFile('ChangeGraph-backlog.csv',csv(state.tasks,['id','title','requirement','status','priority','owner','points']),'text/csv');toast('Backlog exported');break;case'export-qa':downloadFile('ChangeGraph-test-results.csv',csv(state.tests,['id','name','requirement','component','result','owner','lastRun']),'text/csv');toast('QA results exported');break;case'run-all-tests':state.tests.forEach(t=>{t.result='Passed';t.lastRun='Just now'});addActivity('<strong>You</strong> completed a demo run of all QA scenarios');render();toast('Demo run complete · all scenarios marked passed');break;case'approve-docs':state.docsApproved=!state.docsApproved;addActivity(`<strong>You</strong> ${state.docsApproved?'approved':'reopened'} release documentation`);render();toast(state.docsApproved?'Documentation marked approved':'Documentation approval reopened');break;case'download-doc':downloadFile(`ChangeGraph-${state.doc}.md`,docMarkdown(),'text/markdown');toast('Markdown downloaded');break;case'copy-doc':navigator.clipboard?.writeText(docMarkdown()).then(()=>toast('Document copied')).catch(()=>toast('Copy unavailable in this browser'));break;case'notifications':openModal('Notifications','Recent workspace updates.',`<div class="attention-list">${state.activities.slice(0,6).map(a=>`<div class="activity-row"><div class="activity-avatar">${a.initials}</div><div class="activity-copy">${a.text}</div><span class="activity-time">${a.time}</span></div>`).join('')}</div>`,`<button class="btn primary" data-action="close-modal">Done</button>`);break;case'activity-log':openModal('Workspace activity','Recent product and delivery events.',`<div class="activity-list">${state.activities.map(a=>`<div class="activity-row"><div class="activity-avatar">${a.initials}</div><div class="activity-copy">${a.text}</div><span class="activity-time">${a.time}</span></div>`).join('')}</div>`,`<button class="btn primary" data-action="close-modal">Close</button>`);break;case'help':openModal('Help & keyboard shortcuts','A quick guide to the ChangeGraph prototype.',`<div class="criteria-list"><div class="criteria-item"><span class="check-square"></span><span><strong>Overview</strong> — Delivery pulse, risk signals and release readiness.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Requirements</strong> — Search, filter, create and inspect product requirements.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Dependencies</strong> — Select a component and inspect direct relationships.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Backlog</strong> — Inspect work items and change their status.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>QA</strong> — Run demo checks and track test outcomes.</span></div><div class="criteria-item"><span class="check-square"></span><span><strong>Documentation</strong> — Review and export release documents.</span></div></div><div class="doc-callout">Shortcut: press Ctrl/⌘ + K to open workspace search. Demo changes are saved in this browser. Connected enterprise workspaces persist to PostgreSQL.</div>`,`<button class="btn primary" data-action="close-modal">Got it</button>`);break;case'command':openCommand();break;case'profile-menu':{const u=window.CG_SESSION||{};const role=window.CG_AUTH?.roleConfig?.[u.role]?.label||'Workspace user';openModal('Workspace profile',`Signed in as ${esc(u.displayName||u.name||'Workspace user')}.`,`<p class="drawer-desc">${esc(role)} · Retail Banking workspace</p><div class="doc-callout">${u.isDemo?'Demo identity · local sandbox':'Enterprise identity · Supabase Auth'}</div><button class="btn danger" data-action="reset-demo" style="margin-top:12px">Reset demo data</button>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="logout">Sign out</button>`);break;}case'edit-doc':{const current=docMarkdown();openModal('Edit document draft','Update the working document in Markdown. Changes are saved to the workspace.',`<div class="form-field"><label>Document content</label><textarea id="doc-edit-content" style="min-height:300px;font:12px/1.6 ui-monospace,monospace">${esc(current)}</textarea></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-doc">Save draft</button>`,true);break;}case'save-doc':{const value=document.getElementById('doc-edit-content')?.value;if(value?.trim()){state.docOverrides={...(state.docOverrides||{}),[state.doc]:value};addActivity(`<strong>${esc(window.CG_SESSION?.displayName||'User')}</strong> updated ${state.doc} documentation`);closeModal();render();toast('Document draft saved')}break;}case'reset-demo':state=defaultState();persist();closeModal();setView('overview');toast('Demo workspace has been reset');break;}}
 if(e.target.matches('[data-close-modal]'))closeModal();if(e.target.matches('[data-close-drawer]'))drawerRoot.innerHTML='';
 const submit=e.target.closest('[data-submit-form]');if(submit){const f=document.getElementById(submit.dataset.submitForm);if(f){if(!f.reportValidity())return;handleSubmit(f)} }
});
document.addEventListener('submit',e=>{if(['requirement-form','change-form','task-form','edit-req-form'].includes(e.target.id)){e.preventDefault();handleSubmit(e.target)} });
document.addEventListener('change',e=>{if(e.target.id==='req-status'){state.reqStatus=e.target.value;render()}if(e.target.id==='req-priority'){state.reqPriority=e.target.value;render()}if(e.target.id==='qa-filter'){state.qaFilter=e.target.value;render()}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='req-search'){state.reqSearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const val=state.reqSearch;render();const input=document.getElementById('req-search');if(input){input.focus();input.setSelectionRange(val.length,val.length)}},160)}});
function openCommand(){const body=`<div class="form-field"><label>Search workspace</label><input id="command-search" placeholder="Search requirements, work items, components…" autofocus /></div><div id="command-results" class="criteria-list">${state.requirements.slice(0,4).map(r=>`<button class="component-list-item" data-open-req="${r.id}">${ic('file')} ${r.id} · ${esc(r.title)}</button>`).join('')}</div>`;openModal('Search ChangeGraph','Jump to a requirement, work item or area.',body,`<button class="btn" data-action="close-modal">Close</button>`);setTimeout(()=>document.getElementById('command-search')?.focus(),30)}
document.addEventListener('input',e=>{if(e.target.id==='command-search'){const q=e.target.value.toLowerCase();const results=[...state.requirements.map(r=>({id:r.id,title:r.title,type:'requirement'})),...state.tasks.map(t=>({id:t.id,title:t.title,type:'work item'}))].filter(x=>(x.id+' '+x.title).toLowerCase().includes(q)).slice(0,8);document.getElementById('command-results').innerHTML=results.length?results.map(x=>`<button class="component-list-item" ${x.type==='requirement'?`data-open-req="${x.id}"`:`data-open-task="${x.id}"`}>${ic(x.type==='requirement'?'file':'kanban')} ${x.id} · ${esc(x.title)}</button>`).join(''):'<div class="section-note">No matching records.</div>'}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Escape'){closeModal();drawerRoot.innerHTML=''}});
render();
